}

fun Storage.load() {
    return Storage.fromCell(contract.getData());
}

fun Storage.save(self) {
    contract.setData(self.toCell());
}

struct(0x00000001) Increment {}
struct(0x00000002) Reset {}

type CounterMessage = Increment | Reset;

fun onInternalMessage(in: InMessage) {
    // Пустое сообщение — пополнение баланса.
    if (in.body.isEmpty()) {
        return;
    }

    val msg = lazy CounterMessage.fromSlice(in.body);
    var storage = Storage.load();

    match (msg) {
        Increment => {
            storage.counter += 1;
        }
        Reset => {
            assert (in.senderAddress == storage.owner) throw 401;
            storage.counter = 0;
        }
        else => {
            throw 0xFFFF;
        }
    }

    storage.save();
}

get fun getCounter(): int {
    val storage = Storage.load();
    return storage.counter;
}
```

При деплое начальная ячейка данных должна содержать **адрес владельца, затем ноль в 64 битах**. Например, через `@ton/core`:

```typescript
beginCell().storeAddress(owner).storeUint(0, 64).endCell()
```

Сообщения отправляются из кошелька с TON на комиссии. Тело — 32-битный opcode: `1` увеличивает число на один для любого отправителя, `2` сбрасывает его только для владельца; остальным возвращается ошибка `401`. `getCounter()` читает значение без отправки транзакции.
